import { chromium, expect } from '@playwright/test';
import { mkdirSync, mkdtempSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
// Reuse the deterministic two-page PDF fixture generated by the reader smoke test.
const fixture = readFileSync('artifacts/pdf-smoke-fixture.pdf');
mkdirSync('.tmp', { recursive: true });
const extension = resolve('apps/extension/dist-chromium');
const context = await chromium.launchPersistentContext(mkdtempSync(resolve('.tmp/batch-smoke-')), { headless: true, channel: 'chromium', args: [`--disable-extensions-except=${extension}`, `--load-extension=${extension}`], viewport: { width: 1280, height: 1000 } });
try {
 const worker = context.serviceWorkers()[0] ?? await context.waitForEvent('serviceworker');
 const id = new URL(worker.url()).host;
 const root = `chrome-extension://${id}`;
 await worker.evaluate(() => {
   const original = globalThis.fetch;
   globalThis.__batchReady = false; globalThis.__batchCalls = []; globalThis.__batchLines = [];
   globalThis.fetch = async (input, init) => {
     const url = String(input);
     if (!url.startsWith('https://api.openai.com/v1')) return original(input, init);
     globalThis.__batchCalls.push({ url, method: init?.method ?? 'GET' });
     if (url.endsWith('/files')) {
       globalThis.__batchLines = (await init.body.get('file').text()).trim().split('\n').map(JSON.parse);
       return Response.json({ id: 'file-input' });
     }
     if (url.endsWith('/batches')) return Response.json({ id: 'batch-test', status: 'validating' });
     if (url.endsWith('/content')) return new Response(globalThis.__batchLines.slice().reverse().map(line => JSON.stringify({ custom_id: line.custom_id, response: { status_code: 200, body: { choices: [{ finish_reason: 'stop', message: { content: JSON.stringify({ regions: [{ x: .09, y: .15, width: .8, height: .15, source: 'PDF TEST PAGE ONE', translation: '這是背景批次翻譯的測試頁面' }] }) } }] } } })).join('\n'));
     return Response.json({ id: 'batch-test', status: globalThis.__batchReady ? 'completed' : 'in_progress', output_file_id: globalThis.__batchReady ? 'file-output' : null });
   };
 });
 const popup = await context.newPage(); await popup.goto(`${root}/popup.html`);
 await popup.evaluate(async () => {
   const result = await globalThis.chrome.runtime.sendMessage({ type: 'mt:extension-control', command: { kind: 'replace-api-key', provider: 'openai', apiKey: 'synthetic-test-key' } });
   if (!result.ok) throw new Error(JSON.stringify(result));
 });
 await popup.close();
 let page = await context.newPage(); const errors = []; page.on('pageerror', e => errors.push(e.message));
 const open = async () => {
   await page.goto(`${root}/pdf.html`);
   await page.locator('#file').setInputFiles({ name: 'test.pdf', mimeType: 'application/pdf', buffer: fixture });
   await expect(page.locator('#pdf-page')).toBeVisible({ timeout: 30000 });
   await page.locator('#translation-mode').selectOption('batch');
   await expect(page.locator('#batch-start')).toBeEnabled();
 };
 await open();
 await expect(page.getByRole('button', { name: '翻译当前页', exact: true })).toBeVisible();
 await page.locator('#batch-start').click();
 await expect(page.locator('#batch-status')).toContainText('背景處理中', { timeout: 30000 });
 expect(await worker.evaluate(() => globalThis.__batchLines.length)).toBe(2);
 const lines = await worker.evaluate(() => globalThis.__batchLines);
 expect(lines[0].body.model).toBe('gpt-5-mini'); expect(lines[0].body.reasoning_effort).toBe('low');
 expect(lines[0].body.messages[1].content[1].image_url.url).toMatch(/^data:image\/jpeg;base64,/);
 console.log('PASS entire PDF prepared and submitted through Files and Batch APIs; immediate translation retained');
 await page.close();
 await worker.evaluate(() => { globalThis.__batchReady = true; globalThis.chrome.alarms.create('anderson-pdf-batch-poll', { when: Date.now() + 100 }); });
 // No reader tab is open while the alarm imports and caches the output.
 await expect.poll(async () => worker.evaluate(async () => {
   const db = await new Promise((resolve, reject) => { const r = indexedDB.open('anderson-pdf-batches', 1); r.onsuccess = () => resolve(r.result); r.onerror = reject; });
   const jobs = await new Promise(resolve => { const r = db.transaction('jobs').objectStore('jobs').getAll(); r.onsuccess = () => resolve(r.result); }); db.close();
   return jobs[0]?.status;
 }), { timeout: 30000 }).toBe('completed');
 page = await context.newPage(); page.on('pageerror', e => errors.push(e.message)); await open();
 await expect(page.locator('#cache-state')).toContainText('已載入快取譯文');
 await expect(page.locator('#batch-status')).toContainText('快取 2/2');
 await expect.poll(() => page.locator('#pdf-page').evaluate(img => img.complete && img.naturalWidth > 0)).toBe(true);
 await page.screenshot({ path: 'artifacts/pdf-batch-completed.png' });
 await page.locator('#next').click(); await expect(page.locator('#cache-state')).toContainText('第 2 頁已載入快取譯文');
 console.log('PASS background completion with reader closed, unordered result matching, SVG display and persistent cache on reopen');
 const postsBefore = await worker.evaluate(() => globalThis.__batchCalls.filter(c => c.url.endsWith('/batches') && c.method === 'POST').length);
 await page.locator('#batch-start').click(); await expect(page.locator('#batch-status')).toContainText('完成，譯文已快取');
 expect(await worker.evaluate(() => globalThis.__batchCalls.filter(c => c.url.endsWith('/batches') && c.method === 'POST').length)).toBe(postsBefore);
 console.log('PASS cached pages skip paid Batch requests');
 await page.locator('#clear-cache').click(); await expect(page.locator('#cache-state')).toContainText('快取已清除');
 await page.locator('#translation-mode').selectOption('instant'); await expect(page.locator('#batch-controls')).toBeHidden();
 await expect(page.getByRole('button', { name: '翻译当前页', exact: true })).toBeVisible();
 expect(errors).toEqual([]);
 console.log('PASS clear cache and return to immediate mode');
} catch (error) { for (const page of context.pages()) console.log(await page.locator('body').innerText({ timeout: 1000 }).catch(() => '')); throw error; }
finally { await context.close(); }
